import * as React from "react"
import { Link } from "gatsby"
import { StaticImage } from "gatsby-plugin-image"
import Header from "../components/Header"
import Seo from "../components/Seo"
import { ArrowRight } from "../components/Icons"
import { tagFromSearch } from "../lib/visit-log"
import * as s from "../components/landing/AdLanding.module.css"

/**
 * Where a scanned advert lands — MTC-FCS-037 / 038.
 * ============================================================================
 * The QR in every Facebook-group image points at `/website?id=<code>`, which is
 * the address Nate specified. This is that page.
 *
 * ── IT IS NOT THE BUILDER ──────────────────────────────────────────────────
 * Somebody who just photographed a picture in a group has about four seconds of
 * patience and no reason yet to trust us. Dropping them straight into a
 * six-step wizard asks for work before showing the thing being offered, so this
 * shows the offer, shows what the finished site looks like, and has one button.
 *
 * ── THE ID IS ALREADY RECORDED BY THE TIME THIS RENDERS ────────────────────
 * `onRouteUpdate` in gatsby-browser.js writes the visit before any page
 * component mounts, so nothing here has to remember to do it. The tag is read
 * again only to carry it into the builder's URL, which keeps it visible if
 * somebody bookmarks or shares the link from there.
 */

const POINTS = [
  "Built for your trade, not a generic template",
  "Works properly on a phone — that is where your customers are",
  "Tap-to-call and a quote form that reaches you",
  "Your services, your areas, your photographs",
  "Live in 24–48 hours",
]

const STEPS = [
  {
    title: "Tell us about the work",
    body: "Your trade, the jobs you take, and where you take them. Two minutes, no account needed.",
  },
  {
    title: "Watch it build itself",
    body: "The site appears as you answer. Change the wording, the colours and the pictures until it looks like your business.",
  },
  {
    title: "Put it online",
    body: "Download it and host it anywhere for nothing, or let us host it on your own address.",
  },
]

const AdLandingPage = ({ location }) => {
  const [tag, setTag] = React.useState("")

  React.useEffect(() => {
    setTag(tagFromSearch(location?.search || ""))
  }, [location])

  // Carried through so the builder's own URL still says where they came from.
  const builderHref = tag ? `/website-builder?id=${tag}` : "/website-builder"

  return (
    <>
      <Header />
      <main className={s.page}>
        <section className={s.hero}>
          <div className="container">
            <div className={s.grid}>
              <div>
                <p className={s.eyebrow}>Free website · contractors only</p>
                <h1 className={s.title}>
                  Your own website, <em>free to build</em> — not a Facebook page
                </h1>
                <p className={s.lead}>
                  We build contractors a proper website: your services, your areas, your photos,
                  and a quote form that actually reaches you. Building it costs nothing. You only
                  pay if you want us to host it.
                </p>

                <ul className={s.points}>
                  {POINTS.map(point => (
                    <li key={point}>
                      <span className={s.tick} aria-hidden="true">
                        ✓
                      </span>
                      <span>{point}</span>
                    </li>
                  ))}
                </ul>

                <div className={s.actions}>
                  <Link to={builderHref} className="btn btn--lg">
                    Build mine — free
                    <ArrowRight className="btn__arrow" />
                  </Link>
                  <Link to="/invoice-builder" className={`btn btn--lg ${s.secondary}`}>
                    See the free invoice tool
                  </Link>
                </div>

                <p className={s.price}>
                  <strong>$0 to build.</strong> Hosting on your own address is $15/month, cancel
                  any time. No design fee, no contract.
                </p>

                {tag ? (
                  <p className={s.from}>
                    Thanks for scanning — reference <strong>{tag}</strong>.
                  </p>
                ) : null}
              </div>

              <div className={s.frame}>
                <div className={s.frameBar}>
                  <span className={s.dot} />
                  <span className={s.dot} />
                  <span className={s.dot} />
                  <span className={s.frameUrl}>ridgelineroofing.freecontractorservices.com</span>
                </div>
                <StaticImage
                  src="../images/site-thumb-roofing.jpg"
                  alt="An example contractor website built with this tool"
                  className={s.shot}
                  placeholder="blurred"
                  layout="fullWidth"
                />
              </div>
            </div>
          </div>
        </section>

        <section className={s.steps}>
          <div className="container">
            <div className={s.stepGrid}>
              {STEPS.map((step, i) => (
                <div className={s.step} key={step.title}>
                  <span className={s.stepNo}>{String(i + 1).padStart(2, "0")}</span>
                  <h2 className={s.stepTitle}>{step.title}</h2>
                  <p className={s.stepBody}>{step.body}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        <section className={s.tail}>
          <div className="container">
            <h2 className={s.tailTitle}>It takes about two minutes to see yours.</h2>
            <Link to={builderHref} className="btn btn--lg">
              Start building
              <ArrowRight className="btn__arrow" />
            </Link>
            <p className={s.tailNote}>
              No card, no account, nothing to cancel. You will see the finished site before you
              decide anything.
            </p>
          </div>
        </section>
      </main>
    </>
  )
}

export const Head = () => (
  <Seo
    title="Your free contractor website"
    description="Contractors: a proper website with your services, areas and photos. Free to build, $15/month to host."
  />
)

export default AdLandingPage
